import streamlit as stfrom zhipuai import ZhipuAI# --- 1. 页面基础配置 ---st.set_page_config(    page_title="运维复习助手",    page_icon="🛡️",    layout="centered")st.title("🛡️ 运维模拟面试官 (ZhipuAI 版)")st.caption("基于 GLM-4 系列模型的私人运维导师 | 动态配置")# --- 2. 侧边栏配置 (动态参数配置区) ---with st.sidebar:    st.header("⚙️ 模型与配置")        # 动态模型选择下拉框    selected_model = st.selectbox(        "选择 GLM 模型型号 (GLM Family)",        options=["glm-4-flash", "glm-4", "glm-4-air", "glm-4-long", "glm-3-turbo"],         index=0,         help="glm-4-flash: 高速低成本；glm-4: 旗舰性能；glm-4-long: 长文本能力"    )        st.markdown("---")        # 【动态 System Prompt (人设配置)】    default_system_prompt = """        你是一位拥有10年经验的资深运维架构师和面试官。        你的目标是通过苏格拉底式的提问，帮助用户复习运维知识。                规则：        1. 每次随机出一个运维领域的题目（Linux, K8s, 网络, 数据库, 中间件）。        2. 用户回答后，不要直接给答案，要追问底层的原理。        3. 如果用户回答错误，请温和地指出并解释正确原理。        4. 保持对话简洁、专业。        """        # 使用 text_area 让人设可编辑    system_prompt_input = st.text_area(        "自定义 AI 人设 (System Prompt)",        value=default_system_prompt,        height=200,        help="修改这里可以定义 AI 的角色、性格、回答规则等。"    )        st.markdown("---")        # 输入 API Key    api_key = st.text_input("请输入智谱 AI API Key", type="password")        st.markdown("---")        # 添加一个重置按钮，方便清空对话    if st.button("🗑️ 清空对话记录"):        st.session_state.messages = []        st.rerun()# --- 3. 初始化对话历史 (Session State) ---if "messages" not in st.session_state:    st.session_state.messages = []# 【处理动态人设：确保第一个消息是用户在侧边栏配置的最新 System Prompt】current_system_prompt = {"role": "system", "content": system_prompt_input}    if st.session_state.messages and st.session_state.messages[0]["role"] == "system":    # 如果 System Prompt 存在，则更新它为当前侧边栏的值    st.session_state.messages[0] = current_system_promptelif not st.session_state.messages or st.session_state.messages[0]["role"] != "system":    # 如果列表为空或第一个不是 system prompt，则插入它    st.session_state.messages.insert(0, current_system_prompt)# --- 4. 渲染历史消息 ---for msg in st.session_state.messages:    # 渲染时跳过 system prompt    if msg["role"] != "system":        with st.chat_message(msg["role"]):            st.write(msg["content"])# --- 5. 核心交互逻辑 ---if prompt := st.chat_input("准备好复习了吗？输入 '开始' 或具体的知识点..."):        if not api_key:        st.toast("⚠️ 请先在左侧侧边栏输入 API Key！", icon="🚫")        st.stop()     # A. 显示用户消息并存入历史    with st.chat_message("user"):        st.write(prompt)    st.session_state.messages.append({"role": "user", "content": prompt})    # B. 调用智谱 AI    client = ZhipuAI(api_key=api_key)        with st.chat_message("assistant"):                try:            response = client.chat.completions.create(                model=selected_model,                    messages=st.session_state.messages, # 包含了最新的人设                stream=True,               )                        # 【关键修复区：手动处理流式输出，解决 SDK 兼容问题】            full_response = ""            message_placeholder = st.empty()                         for chunk in response:                # 检查并获取内容                content = chunk.choices[0].delta.content                if content:                    full_response += content                    # 显示当前已接收的内容，并加上光标效果                    message_placeholder.markdown(full_response + "▌")             message_placeholder.markdown(full_response) # 移除光标，显示最终内容                    except Exception as e:            # 增加详细错误提示，方便排查            st.error(f"调用接口失败，请检查模型名称或 Key 是否正确。错误信息: {e}")            full_response = "接口出错了，请检查配置。"    # C. 将 AI 回复存入历史    st.session_state.messages.append({"role": "assistant", "content": full_response})